# Pure stdlib-free verifier: defines verify(witness), raises AssertionError on any
# failed check. Success = normal return. No imports, no I/O, deterministic, exact integers.

def verify(witness):
    n = witness['n']
    assert witness['ground_set'] == list(range(n))
    assert n == 4
    N = 1 << n  # 16 subsets of the ground set, as bitmasks 0..15
    EXPECTED_DOWNSETS = witness['expected_downset_count']

    def bitcount(m):
        return bin(m).count('1')

    def is_intersecting(fm):
        # Mathlib Set.Intersecting: self-pairs included, so a member equal to the
        # empty set disqualifies the family.
        members = [i for i in range(N) if (fm >> i) & 1]
        for a in range(len(members)):
            if members[a] & members[a] == 0:
                return False
            for b in range(a, len(members)):
                if members[a] & members[b] == 0:
                    return False
        return True

    def is_downset(fm):
        for i in range(N):
            if (fm >> i) & 1:
                sub = i
                while True:
                    if not ((fm >> sub) & 1):
                        return False
                    if sub == 0:
                        break
                    sub = (sub - 1) & i  # next strict submask
        return True

    downsets = [fm for fm in range(1 << N) if is_downset(fm)]
    assert len(downsets) == EXPECTED_DOWNSETS, 'downset count mismatch: %d != %d' % (
        len(downsets), EXPECTED_DOWNSETS)
    equality_attained = False
    for fm in downsets:
        members = [i for i in range(N) if (fm >> i) & 1]
        max_star = 0
        for x in range(n):
            s = sum(1 for i in members if (i >> x) & 1)
            if s > max_star:
                max_star = s
        max_int = 0
        for sub in range(1 << len(members)):
            size = bitcount(sub)
            if size <= max_int:
                continue
            fm2 = 0
            for k in range(len(members)):
                if (sub >> k) & 1:
                    fm2 |= 1 << members[k]
            if is_intersecting(fm2) and size > max_int:
                max_int = size
        assert max_int <= max_star, (
            'star bound violated for downset %d: %d > %d' % (fm, max_int, max_star))
        if max_int == max_star and max_star > 0:
            equality_attained = True
    assert equality_attained, 'tight case (equality) absent; enumeration unfaithful'
